window.products.push({"id":130065,"name":"HQRP 2-Pack Wick Filter Compatible with Vornado EVAP40 Vortex, EVAP3 Vortex Humidifier","category":"homeandappliances","retail price":17.85,"sale price":null,"image":"https://m.media-amazon.com/images/I/719jK6guEvL._AC_SL1500_.jpg","description":"HQRP 2-pack Humidifier Wick Filter Replacement. Compatible with Vornado MD1-0002 / MD1-0001 Filter Replacement and All Vornado Humidifiers EVAP1, EVAP2, EVAP3, EVAP40 Vortex, Model 30, Model 40, Model 50. For replacing the filter turn off and unplug the humidifier, remove the water tank, remove and discard used filter. Install the new filter. Make sure the filter fits flush against the bottom of the unit and snugs adainst the inlet grill. On the EVAP2 you may need to slightly bend the filter to match the curve of the unit. Replace the water tank.","images":["https://m.media-amazon.com/images/I/719jK6guEvL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"HQRP","source_asin":"B019T9VTT8","category_path":"Home & Appliances"},"sku":"BM-130065","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B019T9VTT8","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Appliances.jsonl","source_asin":"B019T9VTT8","price_pending":true,"merchant_ready":false});
